#include <stdlib.h>
#include "../starcraft/game.c"
#include <stdio.h>
static unsigned held,ticks;
static void step(u16 h){game_update(h,h&~held);held=h;ticks++;}
static void tap(u16 k){step(k);step(0);}
static int select_one(int slot){for(int n=0;n<MAX_UNITS&&screen==SCREEN_PLAY&&!won&&!lost;n++){tap(KEY_L);if(u[slot].alive&&u[slot].selected&&selected_count()==1)return 1;}return 0;}
static int move_cursor(int x,int y){int guard=0;while((abs(cx-x)>2||abs(cy-y)>2)&&screen==SCREEN_PLAY&&!won&&!lost&&guard++<3000){u16 h=KEY_R;if(abs(cx-x)>2)h|=cx<x?KEY_RIGHT:KEY_LEFT;if(abs(cy-y)>2)h|=cy<y?KEY_DOWN:KEY_UP;step(h);}step(0);return guard<3000;}
static int order(int slot,int row,int x,int y){if(!select_one(slot))return 0;tap(KEY_B);for(int n=0;menu_open&&menu_cursor!=row&&n<MENU_COUNT;n++)tap(menu_cursor<row?KEY_DOWN:KEY_UP);if(!menu_open||menu_cursor!=row)return 0;tap(KEY_A);if(!move_cursor(x,y))return 0;tap(KEY_A);return 1;}
static int side_building(int type,int complete){for(int i=0;i<MAX_BUILDINGS;i++)if(b[i].alive&&b[i].owner==SIDE&&b[i].type==type&&(!complete||building_complete(i)))return i;return -1;}
static int build(int worker,int type,int row){int x=-1,y=-1,best=0x7fffffff;for(int yy=b[63].y-128;yy<=b[63].y+128;yy+=16)for(int xx=b[63].x-128;xx<=b[63].x+128;xx+=16)if(race_can_site(SIDE,type,xx,yy)&&can_place(type,xx,yy)){int d=dist2(u[worker].x,u[worker].y,xx,yy);if(d<best){best=d;x=xx;y=yy;}}if(x<0)return 0;int ok=order(worker,row,x,y);for(int retry=0;mode==MODE_BUILD&&retry<12;retry++){int fx=-1,fy=-1;for(int yy=b[63].y-128;yy<=b[63].y+128&&fx<0;yy+=16)for(int xx=b[63].x-128;xx<=b[63].x+128;xx+=16){int clear=1;for(int j=0;j<MAX_UNITS;j++)if(u[j].alive&&dist2(u[j].x,u[j].y,xx,yy)<64*64)clear=0;if(clear&&race_can_site(SIDE,type,xx,yy)&&can_place(type,xx,yy)){fx=xx;fy=yy;break;}}if(fx<0)break;move_cursor(fx,fy);tap(KEY_A);printf(" retry%d xy%d,%d mode%d frame%d\n",retry,fx,fy,mode,frame);}printf("build type%d worker%d site%d,%d issued%d frame%d money%d/%d order%d mode%d cursor%d,%d worker%d can%d race%d\n",type,worker,x,y,ok,frame,minerals,gas,u[worker].order,mode,cx,cy,field_ui_build_worker(type),can_place(type,cx,cy),race_can_site(SIDE,type,cx,cy));return ok;}
static void queue_type(int type){move_cursor(b[63].x,b[63].y);tap(KEY_A);for(int i=0;i<8&&train_type!=type;i++)tap(KEY_R);if(selected_building==63&&train_type==type)tap(KEY_A);printf("queue type%d frame%d selected%d count%d mineral%d gas%d\n",type,frame,selected_building,b[63].queue_count,minerals,gas);}
static int morph_spore(int slot){
 move_cursor(b[slot].x,b[slot].y);tap(KEY_A);
 printf("spore selected%d expected%d frame%d\n",selected_building,slot,frame);
 if(selected_building!=slot)return 0;
 tap(KEY_B);for(int n=0;menu_open&&menu_cursor!=MENU_STOP+2&&n<MENU_COUNT;n++)tap(menu_cursor<MENU_STOP+2?KEY_DOWN:KEY_UP);
 if(!menu_open||menu_cursor!=MENU_STOP+2)return 0;tap(KEY_A);
 printf("spore morph frame%d money%d flags%u progress%d under%d\n",frame,minerals,b[slot].flags,b[slot].build_progress,b[slot].under_construction);
 return !!(b[slot].flags&SC64_Z7_SPORE_MORPH_FLAG);
}
int main(void){game_init();tap(KEY_A);for(int i=0;i<3;i++)tap(KEY_RIGHT);tap(KEY_DOWN);tap(KEY_A);tap(KEY_START);
 order(10,MENU_MOVE,1950,80);order(48,MENU_MOVE,1320,1680);order(55,MENU_ATTACK,1320,1650);order(56,MENU_ATTACK,1320,1650);int l[]={53,54,57};for(int j=0;j<3;j++)order(l[j],MENU_ATTACK,1320,1650);order(16,MENU_MOVE,1770,500);for(int i=17;i<=22;i++)order(i,MENU_ATTACK,1770,500);order(7,MENU_ATTACK,1770,500);order(8,MENU_ATTACK,1770,500);order(11,MENU_ATTACK,1770,500);order(13,MENU_ATTACK,1770,500);
 for(int j=5;j<=6;j++){select_one(j);int p=j==5?11:10;move_cursor(m[p].x,m[p].y);tap(KEY_A);printf("mine worker%d order%d target%d frame%d\n",j,u[j].order,u[j].target,frame);}
 queue_type(U_DRONE);queue_type(U_DRONE);int pool=0,den=0,evo=0,spore=0,hydra=0,deploy[240]={0};for(int t=0;t<20000&&screen==SCREEN_PLAY&&!won&&!lost;t++){step(0);if(!pool&&minerals>=200){pool=build(5,B_SPAWNING_POOL,MENU_BARRACKS);}if(!evo&&minerals>=75&&side_building(B_SPAWNING_POOL,1)>=0){for(int i=0;i<MAX_UNITS;i++)if(u[i].alive&&u[i].owner==SIDE&&u[i].type==U_DRONE){evo=build(i,B_EVOLUTION_CHAMBER,MENU_ENG_BAY);break;}}if(!spore&&minerals>=50&&side_building(B_EVOLUTION_CHAMBER,1)>=0&&b[65].alive&&building_complete(65)&&b[65].type==B_CREEP_COLONY){spore=morph_spore(65);}if(!den&&side_building(B_SPAWNING_POOL,1)>=0&&minerals>=100&&gas>=50){for(int i=0;i<MAX_UNITS;i++)if(u[i].alive&&u[i].owner==SIDE&&u[i].type==U_DRONE){den=build(i,B_HYDRALISK_DEN,MENU_ACADEMY);break;}}if(hydra<4&&side_building(B_HYDRALISK_DEN,1)>=0&&minerals>=75&&gas>=25&&b[63].queue_count==0&&b[63].larva){queue_type(U_HYDRALISK);hydra++;}if(frame>=7600){for(int i=68;i<MAX_UNITS;i++)if(!deploy[i]&&u[i].alive&&u[i].owner==SIDE&&u[i].type==U_HYDRALISK){deploy[i]=1;int ok=order(i,MENU_ATTACK,1770,500);printf(" deployed hydra%d ok%d frame%d alive%d\n",i,ok,frame,u[i].alive);break;}}if(frame%600==0)printf("COLONY frame%d evo%d b65alive%d type%d raw%d hp%d under%d x%d y%d sporeIssued%d\n",frame,side_building(B_EVOLUTION_CHAMBER,1),b[65].alive,b[65].type,b[65].raw_type,b[65].hp,b[65].under_construction,b[65].x,b[65].y,spore);if(frame%600==0)printf("OBS frame%d money%d/%d pool%d den%d workers%d,%d q%d fault%d\n",frame,minerals,gas,side_building(B_SPAWNING_POOL,1),side_building(B_HYDRALISK_DEN,1),u[5].alive,u[6].alive,b[63].queue_count,race_z8_sched.fault);}
 printf("END frame%d lost%d money%d/%d pool%d den%d hydra%d fault%d hero alive%d hp%d xy%d,%d\n",frame,lost,minerals,gas,side_building(B_SPAWNING_POOL,1),side_building(B_HYDRALISK_DEN,1),hydra,race_z8_sched.fault,u[10].alive,u[10].hp,u[10].x,u[10].y);for(int i=0;i<MAX_UNITS;i++)if(u[i].alive&&u[i].raw_type==74)printf("END DT%d hp%d xy%d,%d\n",i,u[i].hp,u[i].x,u[i].y);return 0;}
